    'trunks.connection_mode_help' => 'Na osnovu IP adrese: druga strana se identifikuje po IP adresi, a njen kontakt ostaje statički — preporučeni režim za stranu sa fiksnom IP adresom u istoj mreži. Dolazna registracija: druga strana nam šalje SIP REGISTER, a njena adresa se saznaje iz te registracije. Ovaj režim zahteva korisničko ime i lozinku; druga strana njima autentifikuje i registraciju i pozive.',
