    'sound_packs.help_title' => 'Asterisk zvučni paketi',
    'sound_packs.help_body' => 'Preuzima i instalira zvanične Asterisk sistemske poruke i muziku na čekanju sa <code>downloads.asterisk.org</code>. Svaki paket je jedan jezik u jednom formatu; Asterisk reprodukuje format koji odgovara kodeku poziva, a u suprotnom transkodira (g722 za G.722, ulaw/alaw za operatere).<br>- <strong>Core:</strong> sistemske poruke, cifre, govorna pošta. <strong>Extra:</strong> dodatne poruke; prvo mora biti instaliran core paket istog jezika.<br>- <strong>Muzika na čekanju (opsound):</strong> instalira se u <code>/var/lib/asterisk/moh/opsound</code>; da biste je reprodukovali, kreirajte MOH klasu pod nazivom <strong>opsound</strong> na kartici Muzika na čekanju.<br>- <strong>Türkçe (AiPBX):</strong> sopstvene turske poruke AiPBX-a (GitHub izdanje, provereno SHA256); podrazumevani jezik je turski, pa njihovo uklanjanje utišava sistemske poruke. Uklanjanje briše samo fajlove koje je paket instalirao.',
