    'certificates.help_title' => 'Vodič za sertifikate',
    'certificates.help_body' => 'Portal (HTTPS), WebRTC TURNS i SIP-TLS/WSS dele jedan sertifikat; izmene ovde primenjuju se zajedno na Apache, coturn i Asterisk. <b>Let\'s Encrypt</b> je besplatan i sam se obnavlja; domen mora da upućuje na ovaj server, a port 80 mora biti dostupan sa interneta. Ako Vaša organizacija ima sertifikat, <b>otpremite ga</b> (PEM ili PFX); otpremljeni sertifikati se ne obnavljaju automatski, pa otpremite novi pre isteka. Uz <b>samopotpisani</b> sertifikat pregledači prikazuju upozorenje i TURNS ne radi u pregledačima: WebRTC pozivi iza zaštitnih zidova možda neće imati zvuk.',
