    'queue_reports.help_title' => 'Vodič za izveštaje o redovima čekanja',
    'queue_reports.help_body' => 'Svaki poziv koji uđe u red čekanja računa se jednom. <b>Javljeni</b>: povezani sa agentom. <b>Izgubljeni</b>: pozivalac je prekinuo tokom čekanja ili je isteklo vreme reda čekanja. <b>Kratko odustajanje</b>: prekinuto u roku od %d sekundi; ne ulazi u nivo usluge. <b>Nivo usluge</b>: pozivi javljeni u okviru ciljnog vremena, u odnosu na sve pozive osim kratkih odustajanja. <b>ASA</b>: prosečno čekanje javljenih poziva. <b>AHT</b>: prosečno trajanje razgovora. <b>Stopa javljanja</b> (agent): koliko često se agent javio kada mu je red čekanja zvonio. <b>Povratni poziv</b>: izgubljeni poziv smatra se rešenim ako je njegov broj kasnije pozvan sa lokala ili je ponovo zvao i dobio odgovor. Podaci potiču iz Asterisk dnevnika redova čekanja; izveštaj se može preuzeti kao PDF ili Excel.',
