    'ai_tts.help_title' => 'Vodič za Cloud TTS',
    'ai_tts.help_body' => 'Pretvara tekst u prirodan govor pomoću servisa u oblaku (Google, Amazon Polly, Azure, ElevenLabs, OpenAI). Preslušajte rezultat, preuzmite ga kao MP3 ili ga jednim klikom sačuvajte kao <b>najavu</b>: konvertuje se u Asterisk format (8 kHz WAV) i dodaje u Zvuke &amp; najave za IVR, dolazne rute i vremenske uslove (stupa na snagu nakon primene). <b>Ovi servisi se plaćaju</b> i naplaćuju po znaku; svaka sinteza čuva se u istoriji sa brojem znakova. Pristupni ključevi dobijaju se u konzoli svakog dobavljača, čuvaju se šifrovano i nikada se ponovo ne prikazuju na stranici.',
