    'mailtpl.invite_new.subject' => '[{brand}] Vaš nalog je kreiran - postavite lozinku',
    'mailtpl.invite_new.body' => '<p>Poštovani {name},</p><p>Vaš nalog na centrali <strong>{brand}</strong> je spreman. Da biste se prijavili, postavite lozinku pomoću dugmeta ispod.</p>{account_details}{reset_button}<p>Ako dugme ne radi, otvorite ovaj link: {reset_link}</p>{mobile_section}<p><em>Link za lozinku važi 48 sati i radi jednom. Ako niste očekivali ovaj e-mail, obratite se administratoru sistema.</em></p>',
