    'mailtpl.invite.body' => '<p>Poštovani {name},</p><p>Evo novog linka za postavljanje lozinke za <strong>{brand}</strong>.</p>{account_details}{reset_button}<p>Ako dugme ne radi, otvorite ovaj link: {reset_link}</p>{mobile_section}<p><em>Link za lozinku važi 48 sati i radi jednom. Ako ga niste zatražili, obratite se administratoru sistema.</em></p>',
    'mailtpl.password_reset.subject' => '[{brand}] Resetujte lozinku',
    'mailtpl.password_reset.body' => '<p>Poštovani {name},</p><p>Zatraženo je resetovanje lozinke za vaš nalog <strong>{username}</strong>.</p>{reset_button}<p>Ako dugme ne radi, otvorite ovaj link: {reset_link}</p><p><em>Link važi 30 minuta. Ako ga niste zatražili, zanemarite ovaj e-mail; vaša lozinka ostaje ista.</em></p>',
    'mailtpl.voicemail.subject' => 'Nova govorna poruka od {caller} ({duration})',
    'mailtpl.voicemail.body' => '<p>Poštovani {name},</p><p>Imate novu govornu poruku u sandučetu <strong>{mailbox}</strong>.</p><ul><li><strong>Od:</strong> {caller}</li><li><strong>Primljeno:</strong> {date}</li><li><strong>Trajanje:</strong> {duration}</li></ul><p>Ako je snimak priložen, možete ga pustiti direktno ovde. Možete ga preslušati i na portalu ({portal_link}) ili biranjem *97.</p>',
    'mailtpl.fax_received.subject' => 'Primljen novi faks - {department} ({did})',
    'mailtpl.fax_received.body' => '<p>Primljen je novi faks.</p><ul><li><strong>Jedinica:</strong> {department}</li><li><strong>Broj faksa:</strong> {did}</li><li><strong>Od:</strong> {caller}</li><li><strong>Strane:</strong> {pages}</li><li><strong>Primljeno:</strong> {date}</li></ul><p>Faks je priložen kao PDF kada je ta opcija uključena. Svi faksovi su u dolaznim faksovima: {portal_link}</p>',
